        if (i > 0) { while (*s != '\n') s++; s++; }
        if (i < nthreads - 1) { while (*e != '\n') e++; e++; }
        jobs[i].start = s;
        jobs[i].end = e;
    }
    for (int i = 1; i < nthreads; i++)
        pthread_create(&th[i], NULL, worker, &jobs[i]);
    worker(&jobs[0]);
