edits.newText:
static inline uint64_t hash_bytes(const char *s, uint32_t n) {
    // Cheap key: first 8 bytes mixed with length; full memcmp on match keeps
    // correctness for any name set.
    uint64_t w = 0;
    uint32_t m = n < 8 ? n : 8;
    memcpy(&w, s, m);
    return (w * 0x9E3779B97F4A7C15ULL) ^ (n * 0xC2B2AE3D27D4EB4FULL) ^ 1;
}

edits.oldText:
static inline uint64_t hash_bytes(const char *s, uint32_t n) {
    // FNV-1a over 8-byte words with tail handling folded in by caller loop
    uint64_t h = 1469598103934665603ULL;
    uint32_t i = 0;
    for (; i + 8 <= n; i += 8) {
        uint64_t w;
        memcpy(&w, s + i, 8);
        h = (h ^ w) * 1099511628211ULL;
        h ^= h >> 29;
    }
    if (i < n) {
        uint64_t w = 0;
        memcpy(&w, s + i, n - i);
        h = (h ^ w) * 1099511628211ULL;
        h ^= h >> 29;
    }
    return h ? h : 1;
}

