{"content":"// 1BRC Round A - parallel mmap + AVX2 scanner, SoA hash tables
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <pthread.h>
#include <sys/mman.h>
#include <sys/stat.h>

#if defined(__x86_64__)
#include <immintrin.h>
#define HAVE_AVX2 1
#endif

#ifndef NSLOTS
#define NSLOTS 1024
#endif
#define SLOTMASK (NSLOTS - 1)

typedef struct {
    uint64_t key[NSLOTS];        // 0 = empty; hash of name
    const char *name[NSLOTS];
    uint32_t len[NSLOTS];
    int16_t mn[NSLOTS];
    int16_t mx[NSLOTS];
    int64_t sum[NSLOTS];
    int32_t cnt[NSLOTS];
} Table;

static inline uint64_t hash_name(const char *s, uint32_t n) {
    uint64_t w = 0;
    uint32_t m = n < 8 ? n : 8;
    memcpy(&w, s, m);
    uint64_t h = (w * 0x9E3779B97F4A7C15ULL) ^ ((uint64_t)n * 0xC2B2AE3D27D4EB4FULL);
    return h ? h : 1;
}

// returns index; *ins set to 1 if slot is empty and caller must insert
static inline uint32_t table_probe(Table *t, const char *name, uint32_t len,
                                   uint64_t h, int *ins) {
    uint32_t idx = (uint32_t)h & SLOTMASK;
    *ins = 0;
    for (;;) {
        uint64_t k = t->key[idx];
        if (k == h) {
            if (t->len[idx] == len && memcmp(t->name[idx], name, len) == 0)
                return idx;
        } else if (k == 0) {
            *ins = 1;
            return idx;
        }
        idx = (idx + 1) & SLOTMASK;
    }
}

static inline void table_update(Table *t, const char *name, uint32_t len,
                                uint64_t h, int32_t v) {
    int ins;
    uint32_t i = table_probe(t, name, len, h, &ins);
    if (ins) {
        t->key[i] = h;
        t->name[i] = name;
        t->len[i] = len;
        t->mn[i] = (int16_t)v;
        t->mx[i] = (int16_t)v;
        t->sum[i] = v;
        t->cnt[i] = 1;
        return;
    }
    if (v < t->mn[i]) t->mn[i] = (int16_t)v;
    if (v > t->mx[i]) t->mx[i] = (int16_t)v;
    t->sum[i] += v;
    t->cnt[i]++;
}

#ifdef HAVE_AVX2
static inline const char *find_semi(const char *p) {
    const __m256i needle = _mm256_set1_epi8(';');
    for (;;) {
        __m256i v = _mm256_loadu_si256((const __m256i *)p);
        uint32_t m = (uint32_t)_mm256_movemask_epi8(_mm256_cmpeq_epi8(v, needle));
        if (__builtin_expect(m != 0, 1)) return p + __builtin_ctz(m);
        p += 32;
    }
}
#else
static inline const char *find_semi(const char *p) {
    while (*p != ';') p++;
    return p;
}
#endif

typedef struct {
    const char *start;
    const char *end;
    Table tbl;
} Job;

static void *worker(void *arg) {
    Job *j = (Job *)arg;
    Table *t = &j->tbl;
    memset(t, 0, sizeof(*t));
    const char *p = j->start;
    const char *end = j->end;

#ifdef HAVE_AVX2
    const __m256i needle = _mm256_set1_epi8(';');
    while (p < end) {
        // scan for ';', 32B at a time
        const char *q = p;
        uint32_t mask, d;
        for (;;) {
            __m256i v = _mm256_loadu_si256((const __m256i *)q);
            mask = (uint32_t)_mm256_movemask_epi8(_mm256_cmpeq_epi8(v, needle));
            if (__builtin_expect(mask != 0, 1)) break;
            q += 32;
        }
        d = (uint32_t)__builtin_ctz(mask);
        const char *semi = q + d;
        uint32_t len = d + (uint32_t)(q - p);

        uint64_t w = 0;
        if (len >= 8) memcpy(&w, p, 8);
        else memcpy(&w, p, len);
        uint64_t h = (w * 0x9E3779B97F4A7C15ULL) ^ ((uint64_t)len * 0xC2B2AE3D27D4EB4FULL);
        if (!h) h = 1;

        // parse temperature: [-]D.D or [-]DD.D
        const char *r = semi + 1;
        int neg = 0;
        if (*r == '-') { neg = 1; r++; }
        else if (*r == '+') { r++; }
        int tv = *r++ - '0';
        if (*r != '.') { tv = tv * 10 + (*r++ - '0'); }
        r++; // skip '.'
        tv = tv * 10 + (*r - '0');
        if (neg) tv = -tv;

        int ins;
        uint32_t i = table_probe(t, p, len, h, &ins);
        if (ins) {
            t->key[i] = h;
            t->name[i] = p;
            t->len[i] = len;
            t->mn[i] = (int16_t)tv;
            t->mx[i] = (int16_t)tv;
            t->sum[i] = tv;
            t->cnt[i] = 1;
        } else {
            if (tv < t->mn[i]) t->mn[i] = (int16_t)tv;
            if (tv > t->mx[i]) t->mx[i] = (int16_t)tv;
            t->sum[i] += tv;
            t->cnt[i]++;
        }
        p = r + 2; // fraction digit + '\n'
    }
#else
    while (p < end) {
        const char *semi = find_semi(p);
        uint32_t len = (uint32_t)(semi - p);
        uint64_t h = hash_name(p, len);
        const char *r = semi + 1;
        int neg = 0;
        if (*r == '-') { neg = 1; r++; }
        int tv = *r++ - '0';
        if (*r != '.') { tv = tv * 10 + (*r++ - '0'); }
        r++;
        tv = tv * 10 + (*r - '0');
        if (neg) tv = -tv;
        table_update(t, p, len, h, tv);
        p = r + 2;
    }
#endif
    return NULL;
}

static Table merged;

static int cmp_ent(const void *a, const void *b) {
    uint32_t x = (uint32_t)(uintptr_t)a, dummy;
    (void)x; (void)dummy;
    return 0;
}

typedef struct { uint32_t idx; } IdxEnt;

static int cmp_idx(const void *a, const void *b) {
