                merged.name[i] = t->name[s];
                merged.len[i] = t->len[s];
                merged.mn[i] = t->mn[s];
                merged.mx[i] = t->mx[s];
                merged.sum[i] = t->sum[s];
                merged.cnt[i] = t->cnt[s];
