        } else if (k == 0) {
            *ins = 1;
            return idx;
        }
        idx = (idx + 1) & SLOTMASK;
    }
}

static inline void table_update(Table *t, const char *name, uint32_t len,
                                uint64_t h, int32_t v) {
    int ins;
    uint32_t i = table_probe(t, name, len, h, &ins);
    if (ins) {
        t->key[i] = h;
