#else
    while (p < end) {
        const char *semi = find_semi(p);
        uint32_t len = (uint32_t)(semi - p);
        uint64_t h = hash_name(p, len);
        const char *r = semi + 1;
        int neg = 0;
        if (*r == '-') { neg = 1; r++; }
        int tv = *r++ - '0';
        if (*r != '.') { tv = tv * 10 + (*r++ - '0'); }
