            if (tv < t->mn[i]) t->mn[i] = (int16_t)tv;
            if (tv > t->mx[i]) t->mx[i] = (int16_t)tv;
            t->sum[i] += tv;
            t->cnt[i]++;
        }
        p = r + 2; // fraction digit + '\n'
    }
#else
    while (p < end) {
        const char *semi = find_semi(p);
        uint32_t len = (uint32_t)(semi - p);
        uint64_t h = hash_name(p, len);
        const char *r = semi + 1;
        int neg = 0;
        if (*r == '-') { neg = 1; r++; }
        int tv = *r++ - '0';
        if (*r != '.') { tv = tv * 10 + (*r++ - '0'); }
        r++;
        tv = tv * 10 + (*r - '0');
        if (neg) tv = -tv;
        table_update(t, p, len, h, tv);
        p = r + 2;
    }
#endif
    return NULL;
}

static Table merged;

static int cmp_ent(const void *a, const void *b) {
    uint32_t x = (uint32_t)(uintptr_t)a, dummy;
    (void)x; (void)dummy;
    return 0;
}

typedef struct { uint32_t idx; } IdxEnt;

static int cmp_idx(const void *a, const void *b) {
