{"content":"// 1BRC Round A - parallel mmap + AVX2 scanner, SoA tables, branchless temp parse
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <pthread.h>
#include <sys/mman.h>
#include <sys/stat.h>

#if defined(__x86_64__)
#include <immintrin.h>
#define HAVE_AVX2 1
#endif

#ifndef NSLOTS
#define NSLOTS 1024
#endif
#define SLOTMASK (NSLOTS - 1)

typedef struct {
    uint64_t key[NSLOTS];        // 0 = empty; hash of name
    const char *name[NSLOTS];
    uint32_t len[NSLOTS];
    int16_t mn[NSLOTS];
    int16_t mx[NSLOTS];
    int64_t sum[NSLOTS];
    int32_t cnt[NSLOTS];
} Table;

static inline uint32_t table_probe(Table *t, const char *name, uint32_t len,
                                   uint64_t h, int *ins) {
    uint32_t idx = (uint32_t)h & SLOTMASK;
    *ins = 0;
    for (;;) {
        uint64_t k = t->key[idx];
        if (k == h) {
            if (t->len[idx] == len && memcmp(t->name[idx], name, len) == 0)
                return idx;
        } else if (k == 0) {
            *ins = 1;
            return idx;
        }
        idx = (idx + 1) & SLOTMASK;
    }
}

#ifdef HAVE_AVX2
static inline uint32_t scan_mask(const char *q, const __m256i needle) {
    __m256i v = _mm256_loadu_si256((const __m256i *)q);
    return (uint32_t)_mm256_movemask_epi8(_mm256_cmpeq_epi8(v, needle));
}
#endif

typedef struct {
    const char *start;
    const char *end;
    Table tbl;
} Job;

static void *worker(void *arg) {
    Job *j = (Job *)arg;
    Table *t = &j->tbl;
    memset(t, 0, sizeof(*t));
    const char *p = j->start;
    const char *end = j->end;

#ifdef HAVE_AVX2
    const __m256i needle = _mm256_set1_epi8(';');
    while (p < end) {
        const char *q = p;
        uint32_t mask;
        for (;;) {
            mask = scan_mask(q, needle);
            if (__builtin_expect(mask != 0, 1)) break;
            q += 32;
        }
        uint32_t d = (uint32_t)__builtin_ctz(mask);
        const char *semi = q + d;
        uint32_t len = d + (uint32_t)(q - p);

        uint64_t w = 0;
        if (len >= 8) memcpy(&w, p, 8);
        else memcpy(&w, p, len);
        uint64_t h = (w * 0x9E3779B97F4A7C15ULL) ^ ((uint64_t)len * 0xC2B2AE3D27D4EB4FULL);
        if (!h) h = 1;

        // branchless temperature parse: [-]D.D or [-]DD.D
        uint64_t tw;
        memcpy(&tw, semi + 1, 8); // guard region follows mapping; extra bytes ignored
        int n = -(int)((tw & 0xff) == '-');           // 0 or -1
        uint64_t ts = tw >> (n & 8);                  // skip '-' if present
        int c0 = (int)(ts & 0xff) - '0';
        int c1 = (int)((ts >> 8) & 0xff) - '0';
        int c2 = (int)((ts >> 16) & 0xff) - '0';
        int c3 = (int)((ts >> 24) & 0xff) - '0';
        int a1 = (c1 == '.' - '0');                   // one integer digit
        int intpart = c0 * 10 + (a1 ? 0 : c1);
        int frac = a1 ? c2 : c3;
        int tv = intpart * 10 + frac;
        tv = n ? -tv : tv;

        int ins;
        uint32_t i = table_probe(t, p, len, h, &ins);
        if (ins) {
            t->key[i] = h;
            t->name[i] = p;
            t->len[i] = len;
            t->mn[i] = (int16_t)tv;
            t->mx[i] = (int16_t)tv;
            t->sum[i] = tv;
            t->cnt[i] = 1;
        } else {
            if (tv < t->mn[i]) t->mn[i] = (int16_t)tv;
            if (tv > t->mx[i]) t->mx[i] = (int16_t)tv;
            t->sum[i] += tv;
            t->cnt[i]++;
        }
        p = semi + 7; // temp is at most 5 chars + '\n' => next line <= semi+7
        // NOTE: exact advance handled below
        p = (const char *)semi + 1;
        // advance past temp deterministically using parsed layout:
        p += 3 + (a1 ? 0 : 1) + n; // '.'+frac+'\n' (+ int digit) (+ '-')
    }
#else
    while (p < end) {
        const char *semi = p;
        while (*semi != ';') semi++;
        uint32_t len = (uint32_t)(semi - p);
        uint64_t w = 0;
        if (len >= 8) memcpy(&w, p, 8); else memcpy(&w, p, len);
        uint64_t h = (w * 0x9E3779B97F4A7C15ULL) ^ ((uint64_t)len * 0xC2B2AE3D27D4EB4FULL);
        if (!h) h = 1;
        const char *r = semi + 1;
        int neg = (*r == '-');
        const char *r2 = r + neg;
        int a1 = (r2[1] == '.');
        int intpart = (r2[0] - '0') * 10 + (a1 ? 0 : (r2[1] - '0'));
        int frac = a1 ? (r2[2] - '0') : (r2[3] - '0');
        int tv = intpart * 10 + frac;
        if (neg) tv = -tv;
        int ins;
        uint32_t i = table_probe(t, p, len, h, &ins);
        if (ins) {
            t->key[i] = h; t->name[i] = p; t->len[i] = len;
            t->mn[i] = (int16_t)tv; t->mx[i] = (int16_t)tv;
            t->sum[i] = tv; t->cnt[i] = 1;
        } else {
            if (tv < t->mn[i]) t->mn[i] = (int16_t)tv;
            if (tv > t->mx[i]) t->mx[i] = (int16_t)tv;
            t->sum[i] += tv; t->cnt[i]++;
        }
        p = r2 + 3 + (a1 ? 0 : 1) + 1;
