static inline int name_eq(const char *a, const char *b, uint32_t len) {
    uint32_t i = 0;
    uint64_t x, y;
    for (; i + 8 <= len; i += 8) {
        memcpy(&x, a + i, 8);
        memcpy(&y, b + i, 8);
        if (x != y) return 0;
    }
    if (i < len) {
        x = y = 0;
        memcpy(&x, a + i, len - i);
        memcpy(&y, b + i, len - i);
        if (x != y) return 0;
    }
    return 1;
}

static inline uint32_t table_probe(Table *t, const char *name, uint32_t len,
                                   uint64_t h, int *ins) {
    uint32_t idx = (uint32_t)h & SLOTMASK;
    *ins = 0;
    for (;;) {
        uint64_t k = t->key[idx];
        if (k == h) {
            if (t->len[idx] == len && name_eq(t->name[idx], name, len))
                return idx;
        } else if (k == 0) {
            *ins = 1;
            return idx;
        }
        idx = (idx + 1) & SLOTMASK;
    }
}

