{"command":"cd /work/submission && cat > /tmp/pairs.c <<'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
static uint64_t hash_name(const char *s, uint32_t n) {
    uint64_t w = 0; uint32_t m = n < 8 ? n : 8;
    memcpy(&w, s, m);
    uint64_t h = (w * 0x9E3779B97F4A7C15ULL) ^ ((uint64_t)n * 0xC2B2AE3D27D4EB4FULL);
    return h ? h : 1;
}
int main(void){
    char line[256];
    char names[500][128]; int n=0;
    while (fgets(line,sizeof line,stdin)) {
        char *s=strchr(line,';'); if(!s) continue;
        *s=0;
        for(int i=0;i<n;i++) if(!strcmp(names[i],line)) goto next;
        strcpy(names[n++],line);
next:;
    }
    for(int i=0;i<n;i++){
        uint64_t hi=hash_name(names[i],strlen(names[i]));
        for(int j=i+1;j<n;j++)
            if(hi==hash_name(names[j],strlen(names[j])))
                printf("COLLIDE: [%s] vs [%s] -> %lu\n",names[i],names[j],hi);
    }
    printf("n=%d done\n",n);
    return 0;
}
EOF
