// 1BRC Round A - parallel mmap + AVX2 scanner
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <pthread.h>
#include <sys/mman.h>
#include <sys/stat.h>

#if defined(__x86_64__)
#include <immintrin.h>
#define HAVE_AVX2 1
#endif

#define NSLOTS 1024          // power of two; >= 2x max station count (413)
#define SLOTMASK (NSLOTS - 1)

typedef struct {
    uint64_t hash;
    const char *name;
    uint32_t len;
    int32_t mn, mx;
    int64_t sum;
    int32_t cnt;
} Ent;

typedef struct {
    Ent slots[NSLOTS];
} Table;

static inline uint64_t hash_bytes(const char *s, uint32_t n) {
    // FNV-1a over 8-byte words with tail handling folded in by caller loop
    uint64_t h = 1469598103934665603ULL;
    uint32_t i = 0;
    for (; i + 8 <= n; i += 8) {
        uint64_t w;
        memcpy(&w, s + i, 8);
        h = (h ^ w) * 1099511628211ULL;
        h ^= h >> 29;
    }
    if (i < n) {
        uint64_t w = 0;
        memcpy(&w, s + i, n - i);
        h = (h ^ w) * 1099511628211ULL;
        h ^= h >> 29;
    }
    return h ? h : 1;
}

static inline void table_update(Table *t, const char *name, uint32_t len,
                                uint64_t hash, int32_t v) {
    uint64_t h = hash;
    uint64_t idx = h & SLOTMASK;
    for (;;) {
        Ent *e = &t->slots[idx];
        if (e->len == 0) {
            e->hash = hash;
            e->name = name;
            e->len = len;
            e->mn = v;
            e->mx = v;
            e->sum = v;
            e->cnt = 1;
            return;
        }
        if (e->hash == hash && e->len == len && memcmp(e->name, name, len) == 0) {
            if (v < e->mn) e->mn = v;
            if (v > e->mx) e->mx = v;
            e->sum += v;
            e->cnt++;
            return;
        }
        idx = (idx + 1) & SLOTMASK;
    }
}

#ifdef HAVE_AVX2
static inline const char *find_semi(const char *p) {
    const __m256i needle = _mm256_set1_epi8(';');
    for (;;) {
        __m256i v = _mm256_loadu_si256((const __m256i *)p);
        uint32_t m = (uint32_t)_mm256_cmpeq_epi8_mask(v, needle);
        if (__builtin_expect(m != 0, 1)) return p + __builtin_ctz(m);
        p += 32;
    }
}
#else
static inline const char *find_semi(const char *p) {
    while (*p != ';') p++;
    return p;
}
#endif

typedef struct {
    const char *start;
    const char *end;
    Table tbl;
} Job;

static void *worker(void *arg) {
    Job *j = (Job *)arg;
    Table *t = &j->tbl;
    memset(t, 0, sizeof(*t));
    const char *p = j->start;
    const char *end = j->end;

    while (p < end) {
        const char *semi = find_semi(p);
        uint32_t len = (uint32_t)(semi - p);
        uint64_t h = hash_bytes(p, len);

        // parse temperature: [-]D.D or [-]DD.D
        const char *q = semi + 1;
        int neg = 0;
        if (*q == '-') { neg = 1; q++; }
        else if (*q == '+') { q++; }
        int d = *q++ - '0';
        if (*q != '.') { d = d * 10 + (*q++ - '0'); }
        q++; // skip '.'
        d = d * 10 + (*q - '0');
        if (neg) d = -d;

        table_update(t, p, len, h, d);
        p = q + 2; // fraction digit + '\n'
    }
    return NULL;
}

static int cmp_ent(const void *a, const void *b) {
    const Ent *x = *(const Ent **)a;
    const Ent *y = *(const Ent **)b;
    uint32_t n = x->len < y->len ? x->len : y->len;
    int c = memcmp(x->name, y->name, n);
    if (c) return c;
    return (int)x->len - (int)y->len;
}

int main(int argc, char **argv) {
    if (argc < 2) { fprintf(stderr, "usage: %s <file>\n", argv[0]); return 1; }
    const char *path = argv[1];

    int fd = open(path, O_RDONLY);
    if (fd < 0) { perror("open"); return 1; }
    struct stat st;
    if (fstat(fd, &st)) { perror("fstat"); return 1; }
    size_t size = (size_t)st.st_size;

    long psz_l = sysconf(_SC_PAGESIZE);
    size_t psz = psz_l > 0 ? (size_t)psz_l : 4096;
    size_t flen = (size + psz - 1) & ~(psz - 1);
    if (flen == 0) flen = psz;

    char *data = mmap(NULL, flen + psz, PROT_NONE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (data == MAP_FAILED) { perror("mmap reserve"); return 1; }
    if (size) {
        void *r = mmap(data, flen, PROT_READ, MAP_PRIVATE | MAP_FIXED, fd, 0);
        if (r == MAP_FAILED) { perror("mmap file"); return 1; }
    }
    // zero guard page after the file so AVX loads past EOF never fault
    void *g = mmap(data + flen, psz, PROT_READ | PROT_WRITE,
                   MAP_PRIVATE | MAP_ANONYMOUS | MAP_FIXED, -1, 0);
    if (g == MAP_FAILED) { perror("mmap guard"); return 1; }

    int nthreads = 6;
    {
        long na = sysconf(_SC_NPROCESSORS_ONLN);
        // effective quota is 6 CPUs per cgroup; default to that
        (void)na;
    }
    FILE *fq = fopen("/sys/fs/cgroup/cpu.max", "r");
    if (fq) {
        char buf[128];
        if (fgets(buf, sizeof(buf), fq)) {
            long q, per;
            if (sscanf(buf, "%ld %ld", &q, &per) == 2 && q > 0 && per > 0 && strcmp(buf, "max") != 0) {
                int nt = (int)((q + per - 1) / per);
                if (nt >= 1 && nt <= 64) nthreads = nt;
            } else if (strncmp(buf, "max", 3) == 0) {
                long na = sysconf(_SC_NPROCESSORS_ONLN);
                if (na > 0 && na <= 64) nthreads = (int)na;
            }
        }
        fclose(fq);
    }

    if ((size_t)nthreads * 1024 > size) nthreads = size ? (int)(size / 4096 + 1) : 1;
    if (nthreads < 1) nthreads = 1;

    pthread_t th[64];
    Job jobs[64];
    size_t chunk = size / (size_t)nthreads;
    for (int i = 0; i < nthreads; i++) {
        const char *s = data + chunk * (size_t)i;
        const char *e = data + (i == nthreads - 1 ? size : chunk * (size_t)(i + 1));
        if (i > 0) { while (*s != '\n') s++; s++; }
        if (i < nthreads - 1) { while (*e != '\n') e++; e++; }
        jobs[i].start = s;
        jobs[i].end = e;
    }
    for (int i = 1; i < nthreads; i++)
        pthread_create(&th[i], NULL, worker, &jobs[i]);
    worker(&jobs[0]);
    for (int i = 1; i < nthreads; i++)
        pthread_join(th[i], NULL);

    // merge
    static Ent merged[NSLOTS];
    int mcount = 0;
    for (int tI = 0; tI < nthreads; tI++) {
        Table *t = &jobs[tI].tbl;
        for (int s = 0; s < NSLOTS; s++) {
            Ent *e = &t->slots[s];
            if (!e->len) continue;
            uint64_t idx = e->hash & SLOTMASK;
            for (;;) {
                Ent *m = &merged[idx];
                if (!m->len) {
                    *m = *e;
                    mcount++;
                    break;
                }
                if (m->hash == e->hash && m->len == e->len &&
                    memcmp(m->name, e->name, e->len) == 0) {
                    if (e->mn < m->mn) m->mn = e->mn;
                    if (e->mx > m->mx) m->mx = e->mx;
                    m->sum += e->sum;
                    m->cnt += e->cnt;
                    break;
                }
                idx = (idx + 1) & SLOTMASK;
            }
        }
    }

    Ent *ptrs[NSLOTS];
    int k = 0;
    for (int s = 0; s < NSLOTS; s++)
        if (merged[s].len) ptrs[k++] = &merged[s];
    qsort(ptrs, k, sizeof(Ent *), cmp_ent);

    // output
    size_t cap = 1 << 16;
    char *out = malloc(cap);
    size_t o = 0;
    out[o++] = '{';
    for (int i = 0; i < k; i++) {
        Ent *e = ptrs[i];
        if (i) { out[o++] = ','; out[o++] = ' '; }
        memcpy(out + o, e->name, e->len);
        o += e->len;
        out[o++] = '=';

        // min
        int32_t vals[3]; // min, rounded-mean, max
        int64_t num = e->sum * 10;
        int64_t cnt = e->cnt;
        int negmean = num < 0;
        uint64_t un = negmean ? -(uint64_t)num : (uint64_t)num;
        uint64_t r = (un + (uint64_t)(cnt / 2)) / (uint64_t)cnt;
        int32_t mean = negmean ? -(int32_t)r : (int32_t)r;
        if (mean == 0) mean = 0; // normalize -0 -> 0
        vals[0] = e->mn; vals[1] = mean; vals[2] = e->mx;
        for (int vi = 0; vi < 3; vi++) {
            int32_t v = vals[vi];
            uint32_t uv = v < 0 ? (uint32_t)(-v) : (uint32_t)v;
            if (v < 0) out[o++] = '-';
            if (uv >= 100) {
                out[o++] = (char)('0' + uv / 100);
                out[o++] = (char)('0' + (uv / 10) % 10);
            } else if (uv >= 10) {
                out[o++] = (char)('0' + uv / 10);
            }
            out[o++] = (char)('0' + uv % 10); // tenths digit
            // integer part handling: format is like "12.3" — need int part then '.'
        }
    }
    out[o++] = '}';
    fwrite(out, 1, o, stdout);
    fputc('\n', stdout);
    return 0;
}

