                   MAP_PRIVATE | MAP_ANONYMOUS | MAP_FIXED, -1, 0);
    if (g == MAP_FAILED) { perror("mmap guard"); return 1; }

    int nthreads = 6;
    FILE *fq = fopen("/sys/fs/cgroup/cpu.max", "r");
